    },
    "wayfinderNext": {
      "type": "boolean",
      "title": "Offer the next wayfinder ticket",
      "description": "After a wayfinder turn closes a ticket or charts a map, the band offers Next ticket: one press runs /clear, then /wayfinder with the map.",
      "default": true
